# Test hypothesis: each output cell gets the most frequent non-bg value in its 3x3 input block
def get_most_frequent_in_block(grid, r_start, c_start, size=3):
    counts = {}
    for r in range(r_start, min(r_start+size, len(grid))):
        for c in range(c_start, min(c_start+size, len(grid[r]))):
            v = grid[r][c]
            if v != 0 and v != 5:  # Skip background
                counts[v] = counts.get(v, 0) + 1
    if counts:
        max_count = max(counts.values())
        candidates = [v for v, cnt in counts.items() if cnt == max_count]
        return min(candidates)  # Return smallest tiebreaker
    return 0

